/**
 * /security/ —— 安全与数据处置说明
 *
 * 🔴 **本页只写「能在代码里指认」的事实**，取证位置逐条列在各段注释里。
 *    写不出来源的安全声明等于没有，且会在被追问时变成负债。
 *
 * 🔴 **本页必须包含一节「我们不做/未做的」**（`What we do not claim`）。理由同
 *    BSP 文案稿 §6 的精神：安全页最容易变成纯正面清单，读者无法判断边界在哪。
 *    把未做的部分显式写出来，才让「做了的」有信息量。
 *
 * 🔴 `softwareApp={false}`：本页不属于 Whaleal Cart 这个 Shopify 应用。
 *
 * @author 恒哥
 * @since 2026-10-12
 */
import React from 'react';
import { Link } from 'gatsby';
import Layout from '../components/Layout';
import SEO from '../components/SEO';
import { MESSAGING_PRODUCT_NAME, SUPPORT_EMAIL } from '../constants/brand';
import '../styles/marketing.css';
import T from '../i18n/LocalizedText';
import { usePageI18n } from '../i18n';

export default function SecurityPage(pageContext) {
  const { locale, localePath } = usePageI18n(pageContext);

  return (
    <Layout locale={pageContext?.locale}>
      <SEO
        title="Security and data handling at Whaleal"
        description="How provider credentials are stored, what a delivery record contains, how tenant data is separated and how callback endpoints are authenticated."
        pathname="/security/"
        softwareApp={false} hrefLang={locale}
      />
      <div className="mk">
        <header className="mk-hero">
          <span className="mk-eyebrow"><T id="security.001">Security &amp; data</T></span>
          <h1><T id="security.002">What we hold, and how</T></h1>
          <p className="mk-lead"><T id="security.003">
            Because the platform runs against your provider account, it has to hold credentials that
            can send messages on your behalf. That makes how those credentials are stored the most
            important thing on this page.
          </T></p>
        </header>

        <section className="mk-section">
          <h2><T id="security.004">Provider credentials</T></h2>
          <ul className="mk-list">
            <li>
              <T id="security.005"><strong>Sealed with authenticated encryption.</strong> Credentials are encrypted with
              AES-256-GCM. The mode is authenticated, so a tampered ciphertext fails to decrypt
              rather than yielding a corrupted plaintext.
            </T></li>
            <li>
              <T id="security.006"><strong>A fresh initialisation vector per record.</strong> Each encryption generates a
              new 12-byte random IV, so two connections with identical credentials do not produce
              identical ciphertext.
            </T></li>
            <li>
              <T id="security.007"><strong>Rotatable master key.</strong> The ciphertext carries the key version it was
              sealed under, which means the master key can be rotated without first re-encrypting
              every stored record.
            </T></li>
            <li>
              <T id="security.008"><strong>Secrets are not echoed back.</strong> After a connection is saved, the console
              shows a short fingerprint derived from the credential rather than the value itself.
              You can tell that something is configured and that it changed, without the plaintext
              being sent to a browser.
            </T></li>
          </ul>
        </section>

        <section className="mk-section">
          <h2><T id="security.009">What a delivery record contains</T></h2>
          <p className="mk-section-lead"><T id="security.010">
            The record for a sent message holds delivery metadata: the recipient, the provider and
            connection used, the status, the normalized error code, the raw provider status, the
            encoding and the billable segment count, and a retention deadline.
          </T></p>
          <ul className="mk-list">
            <li>
              <T id="security.011"><strong>Message bodies are not stored.</strong> There is no field holding message
              content on any plan. The record is about what happened to the message, not what the
              message said.
            </T></li>
            <li>
              <T id="security.012"><strong>Log retention is bounded.</strong> Each record carries an expiry derived from
              the retention period of the plan, so retention is a property of the data rather than a
              cleanup job somebody has to remember to run.
            </T></li>
            <li>
              <T id="security.013"><strong>Recipient addresses are masked in operational logs.</strong> Diagnostic logging
              shows a masked form of the address. To trace a specific recipient you use the console
              or an export, not the log stream.
            </T></li>
          </ul>
        </section>

        <section className="mk-section">
          <h2><T id="security.014">Tenant separation</T></h2>
          <p className="mk-section-lead"><T id="security.015">
            Every record belongs to a tenant, and queries are scoped to the authenticated tenant
            rather than filtered after the fact. Cross-tenant access to a record by id returns
            not-found rather than forbidden &mdash; a forbidden response would confirm that the
            record exists, which is enough to enumerate other tenants&rsquo; data.
          </T></p>
        </section>

        <section className="mk-section">
          <h2><T id="security.016">Callback endpoints</T></h2>
          <p className="mk-section-lead"><T id="security.017">
            Providers deliver delivery receipts and inbound replies to endpoints authenticated with a
            per-tenant webhook token. The token is carried in the URL query string because providers
            cannot be made to send a custom header on a callback.
          </T></p>
          <p className="mk-section-lead"><T id="security.018">
            We rely on that token rather than verifying a provider-issued request signature.
            Signature verification is on our hardening list and is not something we claim today.
          </T></p>
        </section>

        <section className="mk-section">
          <h2><T id="security.019">What we do not claim</T></h2>
          <ul className="mk-list mk-list-no">
            <li><T id="security.020">No security certification is held or claimed on this site</T></li>
            <li><T id="security.021">No dedicated compliance regime is claimed for any particular destination country</T></li>
            <li><T id="security.022">No provider-request signature verification on callback endpoints</T></li>
            <li><T id="security.023">No independent audit report is published</T></li>
          </ul>
          <p className="mk-section-lead"><T id="security.024">
            If a specific control is what your evaluation depends on, ask us directly and we will
            tell you exactly what is implemented. A security page that only lists strengths is not
            useful for a decision, and we would rather answer the hard question than round it off.
          </T></p>
          <div className="mk-actions">
            <a className="mk-btn mk-btn-primary" href={`mailto:${SUPPORT_EMAIL}`}><T id="security.025">
              Ask a security question
            </T></a>
            <Link className="mk-btn mk-btn-secondary" to={localePath("/platform/")}><T id="security.026">
              How {MESSAGING_PRODUCT_NAME} works
            </T></Link>
          </div>
        </section>
      </div>
    </Layout>
  );
}
